CREATE TABLE IF NOT EXISTS editions (date TEXT PRIMARY KEY, created_at TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stories (id TEXT PRIMARY KEY, date TEXT NOT NULL, section TEXT NOT NULL, headline TEXT NOT NULL, url TEXT);
CREATE INDEX IF NOT EXISTS idx_stories_section_date ON stories(section, date);
CREATE TABLE IF NOT EXISTS feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, story_id TEXT NOT NULL, section TEXT NOT NULL, vote INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, status TEXT, detail TEXT);
CREATE TABLE IF NOT EXISTS devotions (date TEXT NOT NULL, kind TEXT NOT NULL, ref TEXT NOT NULL, PRIMARY KEY (date, kind));
